script:
country_event = {
	id = marauder.1
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		has_marauder_event = no
		has_khan_event = no
		from = {
			OR = {
				is_country_type = dormant_marauders
				is_country_type = marauder_raiders
				is_country_type = awakened_marauders
			}
		}
	}

	immediate = {
		# Heirs of the Khan redirector for the dummy country
		if = {
			limit = {
				from = {
					is_marauder_empire = yes
					has_country_flag = heirs_of_khan_host
				}
				NOT = { has_country_flag = heir_of_the_khan_khan }
			}
			force_show_diplomacy = event_target:great_khan
		}
		else_if = {
			limit = {
				from = {
					is_marauder_empire = yes
					has_country_flag = heirs_of_khan_host
				}
				has_country_flag = heir_of_the_khan_khan
			}
			country_event = { id = marauder.765 scopes = { from = from } }
		}
		else_if = {
			limit = {
				from = {
					OR = {
						is_country_type = dormant_marauders
						is_country_type = marauder_raiders
					}
				}
			}
			# Marauders (communications denied)
			if = {
				limit = {
					OR = {
						has_valid_civic = civic_hive_devouring_swarm
						has_valid_civic = civic_fanatic_purifiers
						has_valid_civic = civic_machine_terminator
						is_genocidal_infernal = yes
					}
					NOR = {
						AND = {
							has_relation_flag = {
								who = from
								flag = current_target
							}
							from = { is_country_type = dormant_marauders }
						}
					}
				}
				country_event = {
					id = marauder.19
					scopes = { from = from }
				}
			}
			# Marauders (while being spontaneously raided)
			else_if = {
				limit = {
					OR = {
						AND = {
							has_relation_flag = {
								who = from
								flag = current_target
							}
							from = { is_country_type = dormant_marauders }
						}
						AND = {
							from = { is_country_type = marauder_raiders }
							any_country = {
								is_country_type = dormant_marauders
								has_country_flag = parent_of@from
								root = {
									has_relation_flag = {
										who = prev
										flag = current_target
									}
								}

							}
						}
					}
					NOT = { has_origin = origin_heirs_of_the_khan }
				}
				country_event = {
					id = marauder.102
					scopes = { from = from }
				}
			}
			# Marauders (while being raided under a contract)
			else_if = {
				limit = {
					OR = {
						AND = {
							has_relation_flag = {
								who = from
								flag = current_hired_target
							}
							from = { is_country_type = dormant_marauders }
						}
						AND = {
							from = { is_country_type = marauder_raiders }
							any_country = {
								is_country_type = dormant_marauders
								has_country_flag = parent_of@from
								root = {
									has_relation_flag = {
										who = prev
										flag = current_hired_target
									}
								}

							}
						}
					}
					NOT = { has_origin = origin_heirs_of_the_khan }
				}
				country_event = {
					id = marauder.112
					scopes = { from = from }
				}
			}
			# Heirs of the Khan unique interaction
			else_if = {
				limit = {
					has_origin = origin_heirs_of_the_khan
				}
				if = {
					limit = {
						from = {
							has_country_flag = marauder_1
						}
					}
					if = {
						limit = {
							has_country_flag = marauder_overlord_1
						}
						country_event = { # Vassal marauder check-in: lets the player toggle reinforcements
							id = marauder.765
							scopes = { from = from }
						}
					}
					else_if = {
						limit = {
							OR = {
								check_variable = {
									which = defeated_heirs_hunters
									value < 1
								}
								has_global_flag = aspiring_khan_spawned
							}
						}
						country_event = { # They wont event talk to you until you have killed a few hunters
							id = marauder.755
							scopes = { from = from }
						}
					}
					else = {
						country_event = {
							id = marauder.760
							scopes = { from = from }
						}
					}
				}
				else = { #For readability we split the diplomacy if you are talking to the other marauders or the ones who exiled you
					country_event = {
						id = marauder.750
						scopes = { from = from }
					}
				}
			}
			# Marauders (while not being raided)
			else = {
				country_event = {
					id = marauder.20
					scopes = { from = from }
				}
			}
		}
		else = {
			# Horde (Khan is dead)
			if = {
				limit = {
					has_global_flag = great_khan_dead
				}
				country_event = {
					id = marauder.665
					scopes = { from = from }
				}
			}
			# Horde (Khan is alive)
			else = {
				country_event = {
					id = marauder.550
					scopes = { from = from }
				}
			}
		}
	}
}

