		if = {
			limit = {
				any_playable_country = {
					has_origin = origin_heirs_of_the_khan
					is_ai = no
				}
				NOT = {
					has_global_flag = heirs_aspiring_khan_spawned
				}
			}
			event_target:marauder_heir = {
				random_system_within_border = {
					save_global_event_target_as = marauder_rally_point
				}
			}
			create_country = {
				name = NAME_Khan_Aspirant
				name_list = event_target:marauder_heir
				species = event_target:marauder_heir
				type = faction
				civics = { civic = civic_great_khans_vision }
				origin = "origin_default"
				flag = {
