					ethic = ethic_fanatic_militarist
					ethic = ethic_xenophobe
				}
				ignore_initial_colony_error = yes
			}
			last_created_country = {
				save_event_target_as = raider_khanate
				set_country_flag = aspiring_khan
				save_global_event_target_as = aspiring_khan
				set_global_flag = heirs_aspiring_khan_spawned
				create_leader = {
					class = commander
					species = owner_main_species
					name = random
					skill = 10
					leader_age_min = 22
					leader_age_max = 40
					randomize_traits = no
					traits = {
						trait = leader_trait_great_khan
						trait = leader_trait_master_gunner
						trait = subclass_commander_admiral
						trait = leader_trait_gunship_specialization_2
						trait = leader_trait_wrecker_2
						trait = leader_trait_reckless_2
						trait = leader_trait_artillerist_2
						trait = leader_trait_demolisher_2
					}
				}
				create_1st_khan_fleet = yes

				last_created_fleet = {
					set_fleet_flag = aspiring_khan
				}

				every_country = {
					limit = {
						is_country_type = dormant_marauders
					}
					set_faction_hostility = {
						target = prev
						set_hostile = no
						set_neutral = yes
					}
				}

				every_playable_country = {
					limit = {
						has_origin = origin_heirs_of_the_khan
					}
					establish_communications_no_message = prev
					country_event = {
						id = nomads.600
					}
				}
				country_event = { #If no one has become the Khan in 10 years, the AI does it
					id = marauder.500
					years = 10
				}
			}
		}
		else_if = {
			limit = {
				has_global_flag = heirs_aspiring_khan_spawned
				exists = event_target:marauder_country_1
			}
			event_target:marauder_country_1 = {
				make_khan_effect = yes
			}
			# The AI claimed the Khanate before any Heir could win the duel.
			remove_global_flag = heirs_aspiring_khan_spawned
			event_target:aspiring_khan? = { destroy_country = yes }
			every_playable_country = {
				limit = {
					has_origin = origin_heirs_of_the_khan
				}
				if = {
					limit = { has_point_of_interest = { poi = marauder_rally_point } }
