country_event = {
	id = marauder.503
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		is_country_type = awakened_marauders
	}

	immediate = {
		fromfrom = {
			save_event_target_as = conquered_planet
			set_owner = root
		}
		from = {
			country_event = { id = marauder.504 }
			change_variable = {
				which = "planets_lost_to_marauder"
				value = 1
			}
			set_country_flag = former_owner@fromfrom
		}
		fromfrom = {
			# Create Defense Armies
			create_army = {
				owner = root
				species = root.species
				type = "defense_army"
			}
			create_army = {
				owner = root
				species = root.species
				type = "defense_army"
			}
			create_army = {
				owner = root
				species = root.species
				type = "defense_army"
			}
			create_army = {
				owner = root
				species = root.species
				type = "defense_army"
			}
			create_army = {
				owner = root
				species = root.species
				type = "defense_army"
			}
			create_army = {
				owner = root
				species = root.species
				type = "defense_army"
			}
			# Create Marauder Pops
			if = {
				limit = { free_housing <= 100 }
				while = {
					count = 4
					limit = {
						pop_amount > 100
					}
					random_owned_pop_group = {
						kill_single_pop = yes
					}
				}
				while = {
					count = 4
					create_pop_group = {
						species = root.species
					}
				}
			}
			if = {
				limit = {
					free_housing > 100
					free_housing < 600
				}
				while = {
					count = 4
					limit = {
						pop_amount > 100
					}
					random_owned_pop_group = {
						kill_single_pop = yes
					}
				}
				while = {
					count = 8
					create_pop_group = {
						species = root.species
					}
				}
			}
			if = {
				limit = { free_housing > 500 }
				while = {
					count = 3
					limit = {
						pop_amount > 100
					}
					random_owned_pop_group = {
						kill_single_pop = yes
					}
				}
				while = {
					count = 12
					create_pop_group = {
						species = root.species
					}
				}
			}
			# Flip Starbase ownership or create a new one
			if = {
				limit = {
					solar_system = {
						exists = starbase
						starbase = {
							fleet = {
								owner = { NOT = { is_same_value = root } }
							}
						}
					}
				}
				solar_system = {
					starbase = { set_owner = root }
				}
			}
			else = {
				solar_system = {
					create_starbase = {
						size = "starbase_marauder"
						owner = root
					}
				}
			}
		}
	}
}

