			event_target:current_marauder_diplomacy = {
				set_faction_hostility = {
					target = event_target:aspiring_khan
					set_hostile = yes
					set_neutral = no
				}
			}
		}
	}

	# Marauder 3 No more reinforcements
	option = {
		name = marauder.750.d
		trigger = {
			has_country_flag = marauder_overlord
			has_country_flag = marauder_overlord_3
			event_target:current_marauder_diplomacy = {
				has_country_flag = marauder_3
				NOT = { has_country_flag = block_reinforcements }
			}
		}
		hidden_effect = {
			event_target:current_marauder_diplomacy = {
				set_country_flag = block_reinforcements
			}
		}
	}

	# Marauder 3 Resume reinforcements
	option = {
		name = marauder.750.e
		trigger = {
			has_country_flag = marauder_overlord
			has_country_flag = marauder_overlord_3
			event_target:current_marauder_diplomacy = {
				has_country_flag = marauder_3
				has_country_flag = block_reinforcements
			}
		}
		hidden_effect = {
			event_target:current_marauder_diplomacy = {
				remove_country_flag = block_reinforcements
			}
		}
	}

	# Terminate communications
	option = {
		name = marauder.20.e
		default_hide_option = yes
	}
}

